window.CFUtils = (() => {
    function showToast(msg, type = 'success') {
        const t = document.getElementById('cf-toast'); if (!t) return;
        const ic = type==='success'?'fa-check-circle':type==='error'?'fa-exclamation-circle':'fa-info-circle';
        const cl = type==='success'?'text-emerald-400':type==='error'?'text-red-400':'text-sky-400';
        t.innerHTML = `<i class="fa-solid ${ic} ${cl} mr-2"></i><span>${msg}</span>`;
        // Use direct style — Tailwind classes can't override #id CSS specificity
        t.style.opacity = '1';
        t.style.transform = 'translateX(-50%) translateY(0)';
        t.style.pointerEvents = 'auto';
        clearTimeout(t._hideTimer);
        t._hideTimer = setTimeout(() => {
            t.style.opacity = '0';
            t.style.transform = 'translateX(-50%) translateY(5rem)';
            t.style.pointerEvents = 'none';
        }, 2800);
    }
    async function copyText(text) {
        try { await navigator.clipboard.writeText(text); showToast('Copied!'); } catch(e) { showToast('Copy failed','error'); }
    }
    function initTheme() {
        const s = localStorage.getItem('cf-theme');
        if (s==='dark'||(!s&&window.matchMedia('(prefers-color-scheme:dark)').matches)) document.documentElement.classList.add('dark');
        updateThemeIcon();
    }
    function toggleTheme() {
        document.documentElement.classList.toggle('dark');
        localStorage.setItem('cf-theme', document.documentElement.classList.contains('dark')?'dark':'light');
        updateThemeIcon();
    }
    function updateThemeIcon() {
        const i = document.getElementById('theme-icon'); if (!i) return;
        i.className = document.documentElement.classList.contains('dark')?'fa-solid fa-sun text-amber-400':'fa-solid fa-moon text-slate-600';
    }
    const CN=[["#FF0000","Red"],["#FF4500","OrangeRed"],["#FF6347","Tomato"],["#FF7F50","Coral"],["#FFA500","Orange"],["#FFD700","Gold"],["#FFFF00","Yellow"],["#ADFF2F","GreenYellow"],["#00FF00","Lime"],["#00FFFF","Cyan"],["#1E90FF","DodgerBlue"],["#0000FF","Blue"],["#4B0082","Indigo"],["#8A2BE2","BlueViolet"],["#FF00FF","Magenta"],["#FF1493","DeepPink"],["#DC143C","Crimson"],["#800000","Maroon"],["#8B4513","SaddleBrown"],["#D2691E","Chocolate"],["#DEB887","BurlyWood"],["#FAEBD7","AntiqueWhite"],["#F5F5DC","Beige"],["#E6E6FA","Lavender"],["#FFC0CB","Pink"],["#DB7093","PaleVioletRed"],["#006400","DarkGreen"],["#228B22","ForestGreen"],["#2E8B57","SeaGreen"],["#90EE90","LightGreen"],["#008080","Teal"],["#87CEEB","SkyBlue"],["#4169E1","RoyalBlue"],["#000080","Navy"],["#191970","MidnightBlue"],["#6A5ACD","SlateBlue"],["#9370DB","MediumPurple"],["#DA70D6","Orchid"],["#DDA0DD","Plum"],["#708090","SlateGray"],["#808080","Gray"],["#C0C0C0","Silver"],["#F5F5F5","WhiteSmoke"],["#FFFFFF","White"],["#000000","Black"]];
    const nc = {};
    function getColorName(hex) {
        if (nc[hex]) return nc[hex]; if (!chroma.valid(hex)) return "Unknown";
        let best={name:"Unknown",delta:Infinity};
        for (const[h,n] of CN){const d=chroma.deltaE(hex,h);if(d<best.delta)best={name:n,delta:d};if(d===0)break}
        nc[hex]=best.name; return best.name;
    }
    function downloadFile(fn, content, type='text/plain') {
        const b=new Blob([content],{type}),l=document.createElement('a');
        l.href=URL.createObjectURL(b);l.download=fn;document.body.appendChild(l);l.click();document.body.removeChild(l);
    }
    return { showToast, copyText, initTheme, toggleTheme, getColorName, downloadFile };
})();


// The API key is held exclusively by the PHP backend.
window.CFAIEngine = (() => {
    const scriptURL = document.currentScript.src;
    function isConfigured() {
        return Boolean(CHROMAFORGE_CONFIG.ENABLE_AI_FEATURES && CHROMAFORGE_CONFIG.AI_ENDPOINT && /^https?:$/.test(location.protocol));
    }
    async function request(action, input) {
        if (!isConfigured()) throw new Error('AI is unavailable. Please open the hosted application.');
        const endpoint = new URL(CHROMAFORGE_CONFIG.AI_ENDPOINT, scriptURL);
        if (endpoint.origin !== location.origin) throw new Error('AI endpoint must be on this website.');
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 45000);
        try {
            const response = await fetch(endpoint.href, {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action, ...input }), signal: controller.signal
            });
            const result = await response.json().catch(() => null);
            if (!response.ok || !result || !Object.prototype.hasOwnProperty.call(result, 'data')) {
                const messages = {400:'Please check your description and color count.', 413:'Your description is too long.', 429:'AI usage limit reached. Please try again later.', 503:'AI is temporarily unavailable. Please try again later.'};
                throw new Error(messages[response.status] || 'AI could not generate a result. Please try again.');
            }
            return result.data;
        } catch (error) {
            if (error.name === 'AbortError') throw new Error('AI request timed out. Please try again.');
            throw error;
        } finally { clearTimeout(timeout); }
    }
    function generatePalette(prompt, count = 5) { return request('palette', { prompt, count }); }
    function suggestVariations(baseColors, count = 3) { return request('variations', { baseColors, count }); }
    function generateBrandColors(industry, style, mood) { return request('brand', { industry, style, mood }); }
    return { isConfigured, generatePalette, suggestVariations, generateBrandColors };
})();
